"use client";

import { Children, isValidElement, useEffect, useId, useRef, useState, type ChangeEvent, type FocusEvent, type ReactNode, type SelectHTMLAttributes } from "react";
import styles from "./list.module.css";

type Option = { value: string; label: ReactNode; disabled?: boolean };
type FilterSelectProps = Omit<SelectHTMLAttributes<HTMLSelectElement>, "children"> & {
  children: ReactNode;
  triggerClassName?: string;
  optionsClassName?: string;
  optionClassName?: string;
};

function optionsFrom(children: ReactNode): Option[] {
  return Children.toArray(children).flatMap(child => {
    if (!isValidElement<{ value?: string; disabled?: boolean; children?: ReactNode }>(child)) return [];
    return [{ value: child.props.value || "", label: child.props.children, disabled: child.props.disabled }];
  });
}

/**
 * A layout-safe select for list filters. Its choices expand beneath the trigger
 * instead of opening the browser's native dropdown over surrounding content.
 */
export function FilterSelect({ children, className, triggerClassName, optionsClassName, optionClassName, defaultValue, value: controlledValue, name, disabled, onChange, onBlur, required, autoFocus, "aria-label": ariaLabel, "aria-invalid": ariaInvalid }: FilterSelectProps) {
  const options = optionsFrom(children);
  const initialValue = String(controlledValue ?? defaultValue ?? options[0]?.value ?? "");
  const [value, setValue] = useState(initialValue);
  const [open, setOpen] = useState(false);
  const listId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const selected = options.find(option => option.value === value) || options[0];
  const isControlled = controlledValue !== undefined;

  useEffect(() => {
    if (isControlled) setValue(String(controlledValue));
  }, [controlledValue, isControlled]);

  useEffect(() => {
    if (!open) return;
    const closeWhenOutside = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", closeWhenOutside);
    return () => document.removeEventListener("pointerdown", closeWhenOutside);
  }, [open]);

  const choose = (nextValue: string) => {
    if (!isControlled) setValue(nextValue);
    setOpen(false);
    onChange?.({ target: { value: nextValue, name }, currentTarget: { value: nextValue, name } } as ChangeEvent<HTMLSelectElement>);
  };

  return <div ref={rootRef} className={[styles.select, className].filter(Boolean).join(" ")}>
    <input type="hidden" name={name} value={isControlled ? String(controlledValue ?? "") : value} required={required} />
    <button type="button" className={[styles.selectTrigger, triggerClassName].filter(Boolean).join(" ")} disabled={disabled} autoFocus={autoFocus} aria-label={ariaLabel} aria-invalid={ariaInvalid} aria-haspopup="listbox" aria-expanded={open} aria-controls={listId} onClick={() => setOpen(current => !current)} onBlur={event => onBlur?.(event as unknown as FocusEvent<HTMLSelectElement>)}>
      <span>{selected?.label}</span><span className={styles.selectChevron} aria-hidden="true" />
    </button>
    {open && <div id={listId} className={[styles.selectOptions, optionsClassName].filter(Boolean).join(" ")} role="listbox" aria-label={ariaLabel}>
      {options.map(option => <button key={option.value} type="button" role="option" aria-selected={option.value === value} className={[styles.selectOption, optionClassName].filter(Boolean).join(" ")} disabled={option.disabled} onMouseDown={event => event.preventDefault()} onClick={() => choose(option.value)}>{option.label}</button>)}
    </div>}
  </div>;
}
